JS="""(function(){
  let globalRate=1;
  function fmt(t){ if(!isFinite(t)) return '0:00'; const m=Math.floor(t/60), s=Math.floor(t%60); return m+':'+(s<10?'0':'')+s; }
  function build(el){
    const src=el.dataset.src; const label=el.dataset.label||'';
    const audio=new Audio(src); audio.preload='metadata'; audio.loop=true;
    const row=document.createElement('div'); row.className='row';
    const btn=document.createElement('button'); btn.className='primary'; btn.textContent='播放';
    const rep=document.createElement('button'); rep.textContent='重听';
    const sel=document.createElement('select');
    [['1','原速 1×'],['0.75','0.75×']].forEach(([v,t])=>{const o=document.createElement('option');o.value=v;o.textContent=t;sel.appendChild(o);});
    const seek=document.createElement('input'); seek.type='range'; seek.min=0; seek.max=1000; seek.value=0;
    const tm=document.createElement('span'); tm.className='time'; tm.textContent='0:00 / 0:00';
    row.append(btn,rep,sel,seek,tm); el.appendChild(row);
    audio.addEventListener('loadedmetadata',()=>{tm.textContent='0:00 / '+fmt(audio.duration);});
    audio.addEventListener('timeupdate',()=>{ if(!audio.duration) return; seek.value=Math.round(audio.currentTime/audio.duration*1000); tm.textContent=fmt(audio.currentTime)+' / '+fmt(audio.duration); });
    btn.onclick=()=>{ if(audio.paused){ audio.play(); btn.textContent='暂停'; } else { audio.pause(); btn.textContent='播放'; } };
    rep.onclick=()=>{ audio.currentTime=0; audio.play(); btn.textContent='暂停'; };
    sel.onchange=()=>{ audio.playbackRate=parseFloat(sel.value); globalRate=audio.playbackRate; };
    seek.oninput=()=>{ if(audio.duration) audio.currentTime=seek.value/1000*audio.duration; };
    audio.playbackRate=globalRate; sel.value=String(globalRate);
    audio.addEventListener('ended',()=>{btn.textContent='播放';});
    el.dataset.ready='1';
  }
  document.addEventListener('DOMContentLoaded',()=>{
    document.querySelectorAll('.clip').forEach(build);
    document.querySelectorAll('a[href^="#"]').forEach(a=>{a.addEventListener('click',()=>{});});
  });
})();
"""
