.brief h3{margin:0 0 6px;font-size:15px;letter-spacing:.06em;color:var(--muted);text-transform:uppercase}
.q{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin:16px 0;box-shadow:0 1px 2px rgba(0,0,0,.03)}
